from threading import Thread
def threaded_compute(n):
    counter = [0]
    def inc():
        for _ in range(n): counter[0] += 1
    threads = [Thread(target=inc) for _ in range(4)]
    for t in threads: t.start()
    for t in threads: t.join()
    return counter[0]

